INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'charity', 'n.', '/ˈtʃærəti/', '慈善;慈善机构;善款', 'Many students give part of their pocket money to charity.', '许多学生把一部分零花钱捐给慈善机构。', 'Charity', 1, 0, 'senior', 'wordlist', 'elective2', 'U3', 'give to charity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'donate', 'v.', '/dəʊˈneɪt/', '捐赠;捐献', 'She decided to donate her old books to a village school.', '她决定把旧书捐给一所乡村学校。', 'Charity', 2, 0, 'senior', 'wordlist', 'elective2', 'U3', 'donate money to', '美音 /ˈdoʊneɪt/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'donation', 'n.', '/dəʊˈneɪʃn/', '捐款;捐赠物', 'The food bank lives on donations from kind people.', '这家食物银行靠好心人的捐赠维持。', 'Charity', 3, 0, 'senior', 'wordlist', 'elective2', 'U3', 'make a donation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'donor', 'n.', '/ˈdəʊnə(r)/', '捐赠者;捐献人', 'A generous donor paid for the whole charity event.', '一位慷慨的捐赠者支付了整场慈善活动的费用。', 'Charity', 4, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a generous donor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'empathy', 'n.', '/ˈempəθi/', '同理心;共情;感同身受', 'Empathy makes us want to help people who are suffering.', '同理心使我们愿意帮助正在受苦的人。', 'Charity', 5, 0, 'senior', 'wordlist', 'elective2', 'U3', 'feel empathy for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'empathise', 'v.', '/ˈempəθaɪz/', '有同感;产生共情', 'It is easier to empathise with others when we recall our own troubles.', '当我们回想起自己的困难时,就更容易对他人感同身受。', 'Charity', 6, 0, 'senior', 'wordlist', 'elective2', 'U3', 'empathise with sb', '美式拼 empathize;美音 /ˈempəθaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suffer', 'v.', '/ˈsʌfə(r)/', '受苦;遭受;受折磨', 'Many families suffer when they lose their homes and have nowhere to go.', '许多家庭在失去家园、无处可去时备受煎熬。', 'Charity', 7, 0, 'senior', 'wordlist', 'elective2', 'U3', 'suffer from', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sufferer', 'n.', '/ˈsʌfərə(r)/', '受苦者;患者', 'Volunteers reached out to the sufferers of the flood with food and warm clothes.', '志愿者给洪灾的受难者送去食物和暖衣。', 'Charity', 8, 0, 'senior', 'wordlist', 'elective2', 'U3', 'help the sufferers', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'moral', 'adj./n.', '/ˈmɒrəl/', '道德的;品行;寓意', 'Giving to those in need is often seen as a moral choice.', '向有需要的人施以援手常被视为一种道德选择。', 'Charity', 9, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a moral choice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'immoral', 'adj.', '/ɪˈmɒrəl/', '不道德的;邪恶的', 'Some people think it immoral to ignore a hungry child.', '有些人认为对一个饥饿的孩子置之不理是不道德的。', 'Charity', 10, 0, 'senior', 'wordlist', 'elective2', 'U3', 'think it immoral', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'responsible', 'adj.', '/rɪˈspɒnsəbl/', '负有责任的;有责任心的', 'We should still help people, even those partly responsible for their own troubles.', '即使是对自身困境负有部分责任的人,我们也应当伸出援手。', 'Charity', 11, 0, 'senior', 'wordlist', 'elective2', 'U3', 'responsible for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'justice', 'n.', '/ˈdʒʌstɪs/', '正义;公正;公平', 'A sense of justice may affect how willing we are to donate.', '正义感可能会影响我们捐助的意愿。', 'Charity', 12, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a sense of justice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'confirm', 'v.', '/kənˈfɜːm/', '证实;确认', 'The study confirms that empathy has a powerful effect on giving.', '这项研究证实同理心对捐助有强大的影响。', 'Charity', 13, 0, 'senior', 'wordlist', 'elective2', 'U3', 'confirm a fact', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'immense', 'adj.', '/ɪˈmens/', '巨大的;无比的', 'Kindness has an immense power to connect strangers.', '善意有把陌生人连结起来的巨大力量。', 'Charity', 14, 0, 'senior', 'wordlist', 'elective2', 'U3', 'immense power', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'prompt', 'v.', '/prɒmpt/', '促使;推动;激起', 'A small act of kindness can prompt others to give as well.', '一个小小的善举能促使别人也去给予。', 'Charity', 15, 0, 'senior', 'wordlist', 'elective2', 'U3', 'prompt sb to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'universal', 'adj.', '/ˌjuːnɪˈvɜːsl/', '普遍的;全体的;通用的', 'Suffering is universal, so anyone can understand another person''s pain.', '苦难是普遍的,因此每个人都能理解他人的痛苦。', 'Charity', 16, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a universal feeling', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'factor', 'n.', '/ˈfæktə(r)/', '因素;要素', 'Empathy is one of the main factors that move us to donate.', '同理心是促使我们捐助的主要因素之一。', 'Charity', 17, 0, 'senior', 'wordlist', 'elective2', 'U3', 'an important factor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'homeless', 'adj.', '/ˈhəʊmləs/', '无家可归的', 'He gave his warm coat to a homeless man on a freezing night.', '在一个寒冷的夜晚,他把暖外套给了一个无家可归的人。', 'Charity', 18, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a homeless person', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'hesitate', 'v.', '/ˈhezɪteɪt/', '犹豫;迟疑', 'Do not hesitate to help someone who is clearly in need.', '对明显有需要的人不要犹豫,大胆去帮。', 'Charity', 19, 0, 'senior', 'wordlist', 'elective2', 'U3', 'hesitate to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'willing', 'adj.', '/ˈwɪlɪŋ/', '愿意的;乐意的', 'When charity is fun, more people are willing to take part.', '当慈善变得有趣,更多人就愿意参与。', 'Charity', 20, 0, 'senior', 'wordlist', 'elective2', 'U3', 'be willing to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'misfortune', 'n.', '/ˌmɪsˈfɔːtʃuːn/', '不幸;厄运', 'We should not blame people for every misfortune in their lives.', '我们不该为别人生活中的每一桩不幸而责怪他们。', 'Charity', 21, 0, 'senior', 'wordlist', 'elective2', 'U3', 'one''s misfortune', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'motivate', 'v.', '/ˈməʊtɪveɪt/', '激励;成为……的动机', 'What motivates people to give to strangers they will never meet?', '是什么促使人们去捐助永远不会见面的陌生人?', 'Charity', 22, 0, 'senior', 'wordlist', 'elective2', 'U3', 'motivate sb to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'characteristic', 'n.', '/ˌkærəktəˈrɪstɪk/', '特征;特点;品质', 'Empathy and a sense of justice are two important moral characteristics.', '同理心与正义感是两种重要的道德品质。', 'Charity', 23, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a moral characteristic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'supply', 'v./n.', '/səˈplaɪ/', '供给;提供;供应(品)', 'The charity supplies needy children with books and warm clothes.', '这家慈善机构为贫困儿童提供书籍和暖衣。', 'Charity', 24, 0, 'senior', 'wordlist', 'elective2', 'U3', 'supply sb with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'relate', 'v.', '/rɪˈleɪt/', '联系;理解(他人感受);讲述', 'Any kind of hardship can help us relate to another person''s pain.', '任何一种艰难都能帮助我们体会到他人的痛苦。', 'Charity', 25, 0, 'senior', 'wordlist', 'elective2', 'U3', 'relate to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'determine', 'v.', '/dɪˈtɜːmɪn/', '决定;确定;查明', 'Empathy often determines whether or not we choose to give.', '同理心常常决定我们是否选择给予。', 'Charity', 26, 0, 'senior', 'wordlist', 'elective2', 'U3', 'determine whether', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'recall', 'v.', '/rɪˈkɔːl/', '回想;回忆起', 'When people recall their own past mistakes, they often grow kinder.', '当人们回想起自己过去的错误时,往往会变得更善良。', 'Charity', 27, 0, 'senior', 'wordlist', 'elective2', 'U3', 'recall the past', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'slip', 'v.', '/slɪp/', '(逐渐)陷入;滑;溜', 'A single piece of bad luck can make a family slip into hardship.', '一次厄运就可能让一个家庭陷入困境。', 'Charity', 28, 0, 'senior', 'wordlist', 'elective2', 'U3', 'slip into', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fierce', 'adj.', '/fɪəs/', '(天气)狂暴的;凶猛的', 'A fierce wind blew in my face as I stood at the window.', '我站在窗前,狂风扑面而来。', 'Charity', 29, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a fierce wind', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'greet', 'v.', '/ɡriːt/', '(以某种方式)回应;打招呼;迎接', 'The old lady greeted every customer with a warm smile.', '那位老太太用温暖的微笑迎接每一位顾客。', 'Charity', 30, 0, 'senior', 'wordlist', 'elective2', 'U3', 'greet sb with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'glare', 'v.', '/ɡleə(r)/', '怒目而视;瞪眼', 'Tired and cold, he used to glare at the supervisor at the window.', '又累又冷,他过去常对窗口的主管怒目而视。', 'Charity', 31, 0, 'senior', 'wordlist', 'elective2', 'U3', 'glare at sb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'supervisor', 'n.', '/ˈsjuːpəvaɪzə(r)/', '主管;监督人;指导者', 'The supervisor handed me the headset and told me to take the order.', '主管把耳机递给我,让我去接单。', 'Charity', 32, 0, 'senior', 'wordlist', 'elective2', 'U3', 'ask the supervisor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'annoyance', 'n.', '/əˈnɔɪəns/', '恼怒;烦恼', 'Cold customers often took out their annoyance on the young worker.', '受冻的顾客常把恼怒发泄在那个年轻员工身上。', 'Charity', 33, 0, 'senior', 'wordlist', 'elective2', 'U3', 'take out one''s annoyance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'confused', 'adj.', '/kənˈfjuːzd/', '困惑的;糊涂的', 'I felt confused when the woman offered to pay for the next car''s order.', '当那位女士提出为后一辆车的订单付钱时,我感到困惑。', 'Charity', 34, 0, 'senior', 'wordlist', 'elective2', 'U3', 'feel confused', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'expression', 'n.', '/ɪkˈspreʃn/', '表情;神色;表达', 'I watched his expression change from annoyed to delighted.', '我看着他的表情从恼怒变成喜悦。', 'Charity', 35, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a facial expression', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'succession', 'n.', '/səkˈseʃn/', '一连串;接连;连续', 'His feelings changed like a succession of photos on a slideshow.', '他的情绪像幻灯片上一连串的照片一样变化着。', 'Charity', 36, 0, 'senior', 'wordlist', 'elective2', 'U3', 'in succession', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disturbed', 'adj.', '/dɪˈstɜːbd/', '心神不安的;烦恼的', 'At first the driver looked disturbed to be standing out in the cold.', '起初那位司机因要站在寒风里而显得心烦意乱。', 'Charity', 37, 0, 'senior', 'wordlist', 'elective2', 'U3', 'look disturbed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'random', 'adj.', '/ˈrændəm/', '随机的;随意的;出人意料的', 'A random act of kindness can change a stranger''s whole day.', '一个随意的善举能改变陌生人一整天的心情。', 'Charity', 38, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a random act of kindness', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'delighted', 'adj.', '/dɪˈlaɪtɪd/', '高兴的;愉快的', 'He was delighted by the kindness of the stranger ahead of him.', '他被前面那位陌生人的善意逗得很开心。', 'Charity', 39, 0, 'senior', 'wordlist', 'elective2', 'U3', 'be delighted by', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impatient', 'adj.', '/ɪmˈpeɪʃnt/', '不耐烦的;没有耐心的', 'He waved kindly at the impatient driver waiting behind him.', '他友好地向后面那位不耐烦的司机挥了挥手。', 'Charity', 40, 0, 'senior', 'wordlist', 'elective2', 'U3', 'an impatient driver', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'humble', 'v./adj.', '/ˈhʌmbl/', '使谦卑;谦逊的', 'The chain of giving humbled every customer at the window that day.', '那天窗口前的施予之链让每位顾客都心生谦卑。', 'Charity', 41, 0, 'senior', 'wordlist', 'elective2', 'U3', 'humble sb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'handful', 'n.', '/ˈhændfʊl/', '一把(的量);少数', 'Customers emptied a handful of change to buy coffee for a stranger.', '顾客们掏出一把零钱,给陌生人买咖啡。', 'Charity', 42, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a handful of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gratitude', 'n.', '/ˈɡrætɪtjuːd/', '感激;感谢之情', 'As they drove off, the customers honked and waved their gratitude.', '顾客们开车离去时,鸣笛挥手表达感激。', 'Charity', 43, 0, 'senior', 'wordlist', 'elective2', 'U3', 'show gratitude', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'flow', 'n./v.', '/fləʊ/', '流;流动;(车流等)往来', 'One kind person can change the whole flow of traffic at a window.', '一个善良的人就能改变窗口前整个车流的走向。', 'Charity', 44, 0, 'senior', 'wordlist', 'elective2', 'U3', 'the flow of traffic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'frost', 'n.', '/frɒst/', '霜;霜冻', 'I sat behind the frost-covered glass on that freezing afternoon.', '在那个寒冷的下午,我坐在结霜的玻璃后面。', 'Charity', 45, 0, 'senior', 'wordlist', 'elective2', 'U3', 'frost-covered glass', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'leather', 'n.', '/ˈleðə(r)/', '皮革', 'The drivers had expected to stay warm on their heated leather seats.', '司机们本以为能舒服地待在加热的皮座椅上。', 'Charity', 46, 0, 'senior', 'wordlist', 'elective2', 'U3', 'leather seats', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'snowflake', 'n.', '/ˈsnəʊfleɪk/', '雪花;雪片', 'Snowflakes gathered on her hair as she stood smiling in the cold.', '她在寒风中微笑站立,雪花落在她的头发上。', 'Charity', 47, 0, 'senior', 'wordlist', 'elective2', 'U3', 'gather snowflakes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'honk', 'v.', '/hɒŋk/', '(使汽车喇叭)鸣响', 'Drivers honked and waved to thank one another for their kindness.', '司机们鸣笛挥手,感谢彼此的善意。', 'Charity', 48, 0, 'senior', 'wordlist', 'elective2', 'U3', 'honk the horn', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u3.01', '①动名词作主语(谓语用单数)', 'A2', 11, '上外版选择性必修第二册 U3 — 动词的 -ing 形式可像名词一样作句子主语,表泛指/经常性的行为;作主语时被看作一个整体,谓语动词用单数(is/makes/...)。', 1, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u3.02', '②动名词作动词宾语', 'A2', 11, '上外版选择性必修第二册 U3 — enjoy, finish, mind, admit, avoid, consider, suggest, keep, practise, deny, imagine, give up, feel like, can''t help 等动词后只接 -ing 形式作宾语,不接 to do。', 2, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u3.03', '③动名词作介词宾语', 'A2', 11, '上外版选择性必修第二册 U3 — 介词(for, at, in, of, by, before, after, without, instead of 等)以及 look forward to / be used to / be committed to 中作介词的 to 后,只能接 -ing 形式。', 3, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ to a food bank helps families who have nothing to eat.', 'Donating', 'Donate', 'Donates', 'Donated', 'A', '句首作主语应用动名词 → Donating;原形/三单/过去式都不能作主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ used books gives them a useful second life.', 'Collect', 'Collecting', 'Collects', 'Collected', 'B', '主语位置用动名词 → Collecting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ the elderly at the nursing home brings them great joy.', 'Visit', 'Visits', 'Visiting', 'Visited', 'C', '作主语用动名词 → Visiting。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ money for the village school is not always easy.', 'Raise', 'Raises', 'Raised', 'Raising', 'D', '主语用动名词 → Raising。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ others in trouble is something we can all do.', 'Helping', 'Help', 'Helps', 'Helped', 'A', '作主语用动名词 → Helping。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ at the animal shelter taught me real responsibility.', 'Volunteer', 'Volunteering', 'Volunteers', 'Volunteered', 'B', '主语位置用动名词 → Volunteering。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ warm clothes to the homeless is a truly kind act.', 'Give', 'Gives', 'Giving', 'Gave', 'C', '作主语用动名词 → Giving。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ part in the charity run made the whole class proud.', 'Take', 'Takes', 'Took', 'Taking', 'D', '主语用动名词 → Taking。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ for a stranger''s coffee can brighten their whole day.', 'Paying', 'Pay', 'Pays', 'Paid', 'A', '作主语用动名词 → Paying。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), '____ kindness to others often costs very little.', 'Show', 'Showing', 'Shows', 'Showed', 'B', '主语用动名词 → Showing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Helping people in need ____ a rewarding experience for everyone.', 'are', 'were', 'is', 'be', 'C', '动名词作主语视作单数,谓语用 is。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Donating blood ____ the lives of strangers every single day.', 'save', 'are saving', 'were saving', 'saves', 'D', '动名词主语用单数谓语 → saves。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Volunteering at the shelter ____ a lot of patience and care.', 'requires', 'require', 'are requiring', 'were requiring', 'A', '动名词主语用单数 → requires。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Caring for sick animals ____ hard but meaningful work.', 'are', 'is', 'were', 'being', 'B', '动名词作主语用单数 → is。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Giving without expecting anything back ____ true kindness.', 'show', 'are showing', 'shows', 'were showing', 'C', '动名词主语用单数 → shows。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Raising money for the village school ____ our main goal this term.', 'remain', 'are remaining', 'were remaining', 'remains', 'D', '动名词主语用单数 → remains。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Reading to blind children ____ them a window into wonderful stories.', 'gives', 'give', 'are giving', 'were giving', 'A', '动名词主语用单数 → gives。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Collecting old toys for the hospital ____ the sick children very happy.', 'make', 'makes', 'are making', 'were making', 'B', '动名词主语用单数 → makes。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Teaching young kids about charity ____ not always easy.', 'are', 'were', 'is', 'be', 'C', '动名词作主语用单数 → is。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.01'), 'Sharing food with the hungry ____ a real difference in their lives.', 'make', 'are making', 'were making', 'makes', 'D', '动名词主语用单数 → makes。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'She enjoys ____ at the local food bank every weekend.', 'helping', 'help', 'to help', 'helped', 'A', 'enjoy 后只接动名词 → helping。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'We have finished ____ all the donated clothes by size.', 'sort', 'sorting', 'to sort', 'sorted', 'B', 'finish 后接动名词 → sorting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'He suggested ____ a charity sale at the school next month.', 'hold', 'to hold', 'holding', 'held', 'C', 'suggest 后接动名词 → holding。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Would you mind ____ these boxes of food to the truck?', 'carry', 'to carry', 'carried', 'carrying', 'D', 'mind 后接动名词 → carrying。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'The volunteers kept ____ until every family had been served.', 'working', 'work', 'to work', 'worked', 'A', 'keep 后接动名词 → working。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'They are considering ____ a fund for the flood victims.', 'start', 'starting', 'to start', 'started', 'B', 'consider 后接动名词 → starting。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'I can''t help ____ sorry for the homeless man out in the cold.', 'feel', 'to feel', 'feeling', 'felt', 'C', 'can''t help doing 忍不住做 → feeling。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'He admitted ____ the donation box at home by mistake.', 'leave', 'to leave', 'left', 'leaving', 'D', 'admit 后接动名词 → leaving。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Please try to avoid ____ food; give it to charity instead.', 'wasting', 'waste', 'to waste', 'wasted', 'A', 'avoid 后接动名词 → wasting。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Our class practises ____ kindness in small ways every day.', 'show', 'showing', 'to show', 'showed', 'B', 'practise 后接动名词 → showing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'She doesn''t mind ____ extra hours to prepare the charity event.', 'spend', 'to spend', 'spending', 'spent', 'C', 'mind 后接动名词 → spending。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'The children enjoyed ____ gift bags for the kids in hospital.', 'make', 'to make', 'made', 'making', 'D', 'enjoy 后接动名词 → making。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'After the storm, the team didn''t give up ____ for the lost dog.', 'searching', 'search', 'to search', 'searched', 'A', 'give up 后接动名词 → searching。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'The shop owner suggested ____ the unsold bread to a shelter.', 'donate', 'donating', 'to donate', 'donated', 'B', 'suggest 后接动名词 → donating。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'We must keep ____ people about the cause until everyone knows.', 'tell', 'to tell', 'telling', 'told', 'C', 'keep 后接动名词 → telling。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Do you feel like ____ in the charity marathon this year?', 'run', 'to run', 'ran', 'running', 'D', 'feel like doing 想做 → running。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'He denied ____ the credit for the donation, though it was his idea.', 'taking', 'take', 'to take', 'took', 'A', 'deny 后接动名词 → taking。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Imagine ____ a whole village with clean water to drink.', 'provide', 'providing', 'to provide', 'provided', 'B', 'imagine 后接动名词 → providing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'The patients enjoy ____ songs sung by the visiting students.', 'hear', 'to hear', 'hearing', 'heard', 'C', 'enjoy 后接动名词 → hearing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.02'), 'Have you finished ____ the posters for the book drive?', 'design', 'to design', 'designed', 'designing', 'D', 'finish 后接动名词 → designing。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Thank you for ____ us with the charity sale all afternoon.', 'helping', 'help', 'to help', 'helped', 'A', '介词 for 后接动名词 → helping。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'She is very good at ____ money for worthy causes.', 'raise', 'raising', 'to raise', 'raised', 'B', '介词 at 后接动名词 → raising。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Instead of ____ the old clothes away, they gave them to charity.', 'throw', 'to throw', 'throwing', 'threw', 'C', 'instead of 后接动名词 → throwing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'We raised a lot of money by ____ homemade cakes at the fair.', 'sell', 'to sell', 'sold', 'selling', 'D', '介词 by 后接动名词 → selling。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'He is interested in ____ for the homeless shelter this winter.', 'volunteering', 'volunteer', 'to volunteer', 'volunteered', 'A', '介词 in 后接动名词 → volunteering。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'I''m really looking forward to ____ part in next month''s charity run.', 'take', 'taking', 'to take', 'took', 'B', 'look forward to 的 to 是介词,后接动名词 → taking。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Before ____ the event, we made a careful plan together.', 'organise', 'to organise', 'organising', 'organised', 'C', '介词 before 后接动名词 → organising。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'After ____ all the donations, the team thanked everyone warmly.', 'count', 'to count', 'counted', 'counting', 'D', '介词 after 后接动名词 → counting。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'They succeeded in ____ enough money to rebuild the school.', 'collecting', 'collect', 'to collect', 'collected', 'A', 'succeed in 的 in 后接动名词 → collecting。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'She thanked the volunteers for ____ their whole weekend to help.', 'give', 'giving', 'to give', 'gave', 'B', '介词 for 后接动名词 → giving。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'We can make a difference by ____ just a little of our time.', 'offer', 'to offer', 'offering', 'offered', 'C', '介词 by 后接动名词 → offering。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'He is very keen on ____ at the animal shelter on Saturdays.', 'work', 'to work', 'worked', 'working', 'D', 'be keen on 的 on 后接动名词 → working。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'They have got used to ____ food to the shelter every Friday.', 'bringing', 'bring', 'to bring', 'brought', 'A', 'be/get used to 的 to 是介词,后接动名词 → bringing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Everyone is capable of ____ kindness to others in some way.', 'show', 'showing', 'to show', 'showed', 'B', 'be capable of 的 of 后接动名词 → showing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Apart from ____ clothes, you can also donate books and toys.', 'donate', 'to donate', 'donating', 'donated', 'C', 'apart from 后接动名词 → donating。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'She left the party without ____ anyone how much she had given.', 'tell', 'to tell', 'told', 'telling', 'D', '介词 without 后接动名词 → telling。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'We are committed to ____ clean water to the whole village.', 'providing', 'provide', 'to provide', 'provided', 'A', 'be committed to 的 to 是介词,后接动名词 → providing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'He felt very proud of ____ a difference in his own community.', 'make', 'making', 'to make', 'made', 'B', 'be proud of 的 of 后接动名词 → making。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'The poster is about ____ warm coats for the winter charity drive.', 'gather', 'to gather', 'gathering', 'gathered', 'C', '介词 about 后接动名词 → gathering。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U3' AND code='se2u3.03'), 'Thank you for ____ so generously to such a worthy cause.', 'contribute', 'to contribute', 'contributed', 'contributing', 'D', '介词 for 后接动名词 → contributing。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Power of Empathy', 'Why do some people give money to a homeless person while others walk past? According to a recent study, the answer often comes down to empathy. When we can imagine the pain that pushed someone into a hopeless situation, we feel closer to them and are more willing to give. The study asked people to donate to those who seemed responsible for their own troubles. Some refused, believing it was wrong to reward bad choices. Interestingly, the people who felt most certain of their own good morals were even less likely to give. Yet when the same people were asked to think about their own past mistakes, they became kinder and gave more freely. The researchers concluded that empathy has immense power. Suffering, after all, is something everyone understands. Any kind of hardship can help us relate to another person''s pain and prompt us to reach out. In the end, it is empathy that connects us and moves us to help.', '说明·同理心如何影响我们是否捐助', 161, '[{"q":"According to the study, what makes people more willing to give?","answer":"A","options":["Being able to imagine the other person''s pain.","Knowing the person very well.","Having plenty of spare money.","Being ordered to by others."],"explanation":"对原文''imagine the pain… more willing to give''的概括转述。"},{"q":"What happened when people thought about their own past mistakes?","answer":"B","options":["They stopped giving altogether.","They felt more sympathy and donated more.","They blamed the sufferers even more.","They forgot about the study."],"explanation":"原文''became kinder and gave more freely''的转述,非照抄。"},{"q":"What did the researchers conclude about empathy?","answer":"A","options":["It has great power to connect people and move them to help.","It is useless in real life.","It only works among family members.","It makes people selfish."],"explanation":"对末段''empathy… connects us and moves us to help''的转述。"}]'::jsonb, '[{"word":"empathy","cn":"同理心"},{"word":"responsible","cn":"负有责任的"},{"word":"prompt","cn":"促使"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Pay It Forward', 'Working at the drive-through window of a fast-food shop was the job I hated most. On freezing days, customers often arrived cold and annoyed, and they took out their bad mood on me. Then, one icy Tuesday afternoon, something changed. A woman with a bright smile came up to the window to pay. "I''ll get the next car''s order as well," she said. I was confused, but she simply explained, "Pay it forward." When the next driver heard what had happened, his face changed from annoyed to surprised, and then to delight. He decided to pay for the order behind him too. The kindness spread from car to car all through the busy hour. People who arrived stressed drove away calm and smiling. Nobody refused to join in. As they left, they honked and waved their thanks. That cold afternoon taught me something simple: it only takes one person, one smile, to warm up even the coldest of days.', '记叙·得来速窗口的善意接力', 159, '[{"q":"How did the narrator feel about the drive-through job at first?","answer":"B","options":["It was their favourite task.","It was the part of the job they disliked most.","It was easy and comfortable.","It paid extremely well."],"explanation":"对''the job I hated most''的转述。"},{"q":"What did the woman mean by ''pay it forward''?","answer":"C","options":["Asking for her own money back.","Paying much less than the real price.","Paying for the next customer''s order as an act of kindness.","Refusing to pay anything at all."],"explanation":"结合上下文,她为下一辆车的订单付钱、把善意传下去。"},{"q":"What lesson did the narrator learn from that afternoon?","answer":"D","options":["Working in winter is completely impossible.","Customers are always rude and selfish.","Kindness usually costs far too much.","A single act of kindness can change everyone''s mood."],"explanation":"对末句''one person, one smile… warm up… the coldest of days''的转述。"}]'::jsonb, '[{"word":"annoyance","cn":"恼怒"},{"word":"delight","cn":"高兴"},{"word":"gratitude","cn":"感激"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Young People Who Give Back', 'Charity is not only for adults. Around the world, many teenagers have started their own non-profit organisations to help others. Jonas, for example, was deeply moved when he saw both animals and young people in need. He set up a group that encourages teenagers to make a difference through volunteer work, providing young people and their families with basic daily necessities. Annie''s story is different. She learned that many children were forced to leave their homes suddenly, taking very few of their own belongings with them. To comfort them, she began making soft bags filled with caring and comforting items, for children from babies to teenagers. These young founders prove an important point: you do not have to be rich or grown-up to change someone''s life. A caring heart and a simple idea are often enough. Their work reminds us that helping others can begin at any age, and that even small actions can bring great comfort to people who are struggling.', '说明·青少年创办的公益组织', 162, '[{"q":"What inspired Jonas to start his organisation?","answer":"A","options":["He saw animals as well as young people who needed help.","Winning a large cash prize.","A school project he disliked.","A long trip abroad."],"explanation":"对''moved when he saw both animals and young people in need''的转述。"},{"q":"What does Annie make for children in difficult situations?","answer":"B","options":["Envelopes full of money.","Soft bags filled with comforting items.","School textbooks only.","Brand-new houses."],"explanation":"对''soft bags filled with caring and comforting items''的转述。"},{"q":"What main point do the two stories share?","answer":"C","options":["Only adults are able to run charities.","Charity is mostly a waste of time.","Young people can also make a real difference.","Money is the only way to help."],"explanation":"对''you do not have to be rich or grown-up to change someone''s life''的转述。"}]'::jsonb, '[{"word":"non-profit","cn":"非营利的"},{"word":"necessities","cn":"必需品"},{"word":"comfort","cn":"安慰"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Teaching Children About Charity', 'How can parents teach young children about charity? One mother found a clever way. She knew that big words and serious lectures would only confuse her kids, so she spoke in simple terms they could easily understand. Instead of giving all the answers herself, she let the children take part in the whole process. She asked them who they would like to help and how they could do it, so the choice felt like their own. Most importantly, she made the activity fun rather than a boring duty. Because of this, her children did not see giving as something difficult or far away. They saw it as a natural and enjoyable part of life. Teaching kindness, the mother believed, works best when children feel they are helping by choice. In this way, small acts of giving slowly grow into a lifelong habit. Children who learn charity young, she said, often become caring and responsible citizens when they grow up.', '说明·一位母亲如何教孩子慈善', 159, '[{"q":"Why did the mother use simple words with her children?","answer":"D","options":["Because she could not speak well herself.","Because the children were already adults.","Because she had very little time.","Because complicated words would only confuse them."],"explanation":"对''big words… would only confuse her kids''的转述。"},{"q":"How did the mother involve her children?","answer":"A","options":["She let them decide who to help and how.","She gave them all the answers herself.","She did everything on her own.","She paid them to take part."],"explanation":"对''asked them who they would like to help and how''的转述。"},{"q":"What does the mother believe about teaching kindness?","answer":"B","options":["It should be a strict daily duty.","It works best when children help by their own choice.","It is impossible for young kids.","It always needs a lot of money."],"explanation":"对''works best when children feel they are helping by choice''的转述。"}]'::jsonb, '[{"word":"confuse","cn":"使困惑"},{"word":"duty","cn":"义务"},{"word":"responsible","cn":"有责任心的"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Creative Ways to Give', 'Charity does not always look the same. Around the world, people have found creative and even funny ways to raise money for good causes. In Dublin, a Women''s Mini Marathon is held every year, and many men join in dressed as women to make the race more cheerful. France became the first country to stop supermarkets from throwing away food they cannot sell. Instead, the shops must give this food to charities that feed the hungry. There is even a story of a dog from Maryland that ran half of a marathon and helped to raise thousands of dollars for charity. These examples show that giving can be joyful and full of imagination. A creative idea can attract more attention, bring people together and make helping others feel like a celebration. When charity is fun, more people are willing to take part. So the next time your school plans an event, why not think of something new and surprising?', '说明·世界各地有创意的慈善方式', 159, '[{"q":"What is special about the marathon in Dublin?","answer":"C","options":["Only children are allowed to run.","Nobody is allowed to watch it.","Many men take part dressed as women.","It lasts for a whole week."],"explanation":"对''many men join in dressed as women''的转述。"},{"q":"What must French supermarkets do with unsold food?","answer":"D","options":["Throw all of it away.","Sell it at a much higher price.","Keep it locked away forever.","Hand it to charities that help the hungry."],"explanation":"对''must give this food to charities that feed the hungry''的转述。"},{"q":"What is the main message of the passage?","answer":"A","options":["Charity can be creative and enjoyable.","Charity should always be serious.","Only rich countries are able to give.","Animals can never help charities."],"explanation":"对''giving can be joyful and full of imagination''的转述。"}]'::jsonb, '[{"word":"marathon","cn":"马拉松"},{"word":"celebration","cn":"庆祝"},{"word":"imagination","cn":"想象力"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Charity in Ancient China', 'Giving to others is not a modern idea. In ancient China, many well-known people were famous for their generous hearts. Fan Li, who lived long ago, is said to have given away all his fortune to the poor three times in his life. Fan Zhongyan of the Song Dynasty turned his own house into a school so that poor children could study there. Zhang Zhongjing, a famous doctor of the Han Dynasty, made warm dumplings to heal the frozen ears of people who had no food in winter. Others offered free sugar or free meals to help families fight illness and hunger. These stories were passed down from one generation to the next, teaching young people the value of kindness. For thousands of years, the spirit of giving has been an important part of Chinese culture. It reminds us that true wealth lies not in what we keep for ourselves, but in what we are willing to share with others.', '说明·古代中国的慈善传统', 160, '[{"q":"What did Fan Zhongyan do to help poor children?","answer":"B","options":["He gave each of them gold.","He made his own home into a place for poor children to study.","He built them brand-new homes.","He taught them how to fight."],"explanation":"对''turned his own house into a school''的转述。"},{"q":"Why did Zhang Zhongjing make warm dumplings?","answer":"C","options":["To sell them for a good price.","To celebrate a grand festival.","To cure the frozen ears of starving people.","To feed only his own family."],"explanation":"对''heal the frozen ears of people who had no food''的转述。"},{"q":"What do these ancient stories teach?","answer":"D","options":["That only doctors are able to help people.","That kindness is a modern invention.","That giving always makes people poor.","That sharing with others is a true form of wealth."],"explanation":"对末句''true wealth lies… in what we are willing to share''的转述。"}]'::jsonb, '[{"word":"generous","cn":"慷慨的"},{"word":"fortune","cn":"财富"},{"word":"wealth","cn":"财富"}]'::jsonb, 2, 'elective2', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'A Book Donation Drive', 'Last month, our class decided to organise a book donation (1)____ for a village school. Many children there have very few books to (2)____. First, we put up colourful (3)____ around the school to tell everyone about our plan. Then students brought in storybooks they no longer (4)____. Within a week, we had (5)____ more than three hundred books. We carefully (6)____ them by age, so that younger children would get picture books. On Friday, we (7)____ all the books into big boxes and sent them to the village. The head teacher there was very (8)____ and thanked us warmly. Helping others made every one of us feel (9)____. We learned that even a small (10)____ can bring a lot of happiness to people in need.', 126, 2, '[{"q":"1","answer":"A","options":["drive","race","meal","storm"],"explanation":"a donation drive 一次募集活动。"},{"q":"2","answer":"B","options":["eat","read","buy","sell"],"explanation":"few books to read 可读的书。"},{"q":"3","answer":"C","options":["prices","meals","posters","tickets"],"explanation":"put up posters 张贴海报。"},{"q":"4","answer":"D","options":["cooked","sold","lost","needed"],"explanation":"no longer needed 不再需要。"},{"q":"5","answer":"A","options":["collected","eaten","broken","spent"],"explanation":"had collected 已收集。"},{"q":"6","answer":"B","options":["threw","sorted","ate","hid"],"explanation":"sorted them by age 按年龄分类。"},{"q":"7","answer":"C","options":["drank","slept","packed","cried"],"explanation":"packed into boxes 装箱。"},{"q":"8","answer":"D","options":["angry","bored","afraid","grateful"],"explanation":"very grateful 非常感激。"},{"q":"9","answer":"A","options":["proud","jealous","bored","afraid"],"explanation":"feel proud 感到自豪。"},{"q":"10","answer":"B","options":["price","act","noise","machine"],"explanation":"a small act 小小的举动。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'Volunteering at the Nursing Home', 'Every Saturday, I (1)____ at a nursing home near my house. At first, I was a little (2)____, because I did not know how to talk to the elderly. But the old people were so (3)____ that I soon relaxed. I help them read letters, water the (4)____, and listen to their wonderful stories about the past. One grandmother always (5)____ me with a warm smile when I arrive. Spending time with them has taught me to be (6)____ and kind. I have also learned that many of them feel (7)____ and simply want someone to talk to. A few minutes of company can really (8)____ their whole day. My friends sometimes ask why I give up my (9)____ time to do this. The answer is simple: helping others makes me truly (10)____.', 133, 2, '[{"q":"1","answer":"C","options":["sleep","shop","volunteer","drive"],"explanation":"volunteer at 在……做志愿者。"},{"q":"2","answer":"D","options":["happy","rich","tall","nervous"],"explanation":"a little nervous 有点紧张。"},{"q":"3","answer":"A","options":["friendly","rude","noisy","lazy"],"explanation":"so friendly 如此友好。"},{"q":"4","answer":"B","options":["prices","flowers","noises","engines"],"explanation":"water the flowers 浇花。"},{"q":"5","answer":"C","options":["throws","sells","greets","breaks"],"explanation":"greets me with a smile 微笑迎接我。"},{"q":"6","answer":"D","options":["lazy","selfish","careless","patient"],"explanation":"be patient 有耐心。"},{"q":"7","answer":"A","options":["lonely","proud","rich","busy"],"explanation":"feel lonely 感到孤独。"},{"q":"8","answer":"B","options":["darken","brighten","waste","ruin"],"explanation":"brighten their day 让他们一天更明亮。"},{"q":"9","answer":"C","options":["lost","full","free","cold"],"explanation":"free time 空闲时间。"},{"q":"10","answer":"D","options":["jealous","bored","angry","happy"],"explanation":"makes me happy 让我快乐。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'Our School Charity Sale', 'To raise money for children in poor areas, our school held a charity (1)____ last weekend. Each class set up a small (2)____ to sell things they had made. My friends and I baked cakes and (3)____ lemonade. We were a little worried that no one would (4)____ our cakes, but they sold out in an hour! Other students sold handmade cards, old books and toys. Teachers also (5)____ by buying lots of food. By the end of the day, we had (6)____ over two thousand yuan. All the money was (7)____ to a charity that helps children go to school. Everyone felt (8)____ to have helped. The event also taught us how to work as a (9)____. We are already planning an even bigger sale for next (10)____.', 129, 2, '[{"q":"1","answer":"A","options":["sale","storm","race","meal"],"explanation":"a charity sale 义卖。"},{"q":"2","answer":"B","options":["price","stall","noise","engine"],"explanation":"set up a stall 摆摊。"},{"q":"3","answer":"C","options":["ate","broke","sold","lost"],"explanation":"sold lemonade 卖柠檬水。"},{"q":"4","answer":"D","options":["throw","break","lose","buy"],"explanation":"no one would buy 没人会买。"},{"q":"5","answer":"A","options":["helped","slept","cried","left"],"explanation":"teachers helped 老师们也来帮忙。"},{"q":"6","answer":"B","options":["lost","raised","wasted","spent"],"explanation":"had raised 筹得。"},{"q":"7","answer":"C","options":["thrown","sold","given","eaten"],"explanation":"was given to a charity 捐给慈善机构。"},{"q":"8","answer":"D","options":["angry","bored","afraid","proud"],"explanation":"felt proud 感到自豪。"},{"q":"9","answer":"A","options":["team","price","noise","machine"],"explanation":"work as a team 作为团队合作。"},{"q":"10","answer":"B","options":["minute","year","second","metre"],"explanation":"next year 明年。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'The Charity Marathon', 'This spring, I signed up for my first charity (1)____. I had been (2)____ for it for a whole month, running a little farther each day. On the morning of the race, thousands of runners (3)____ at the starting line, all hoping to raise money for sick children. My legs felt heavy, but the cheering crowd (4)____ me to keep going. Whenever I wanted to stop, I thought about the children we were (5)____, and I found new strength. Crossing the finish line was an amazing (6)____. I was tired but extremely (7)____ of myself. Together, the runners (8)____ a huge amount of money that day. The best part was knowing that our hard work would (9)____ a real difference. I have already promised myself to (10)____ part again next year.', 131, 2, '[{"q":"1","answer":"C","options":["meal","storm","marathon","price"],"explanation":"a charity marathon 慈善马拉松。"},{"q":"2","answer":"D","options":["sleeping","shopping","cooking","training"],"explanation":"had been training 一直在训练。"},{"q":"3","answer":"A","options":["gathered","slept","cried","left"],"explanation":"runners gathered 跑者聚集。"},{"q":"4","answer":"B","options":["frightened","encouraged","ignored","blocked"],"explanation":"the crowd encouraged me 人群鼓励我。"},{"q":"5","answer":"C","options":["hurting","ignoring","helping","leaving"],"explanation":"the children we were helping 我们在帮助的孩子。"},{"q":"6","answer":"D","options":["price","noise","machine","feeling"],"explanation":"an amazing feeling 美妙的感觉。"},{"q":"7","answer":"A","options":["proud","afraid","bored","jealous"],"explanation":"proud of myself 为自己自豪。"},{"q":"8","answer":"B","options":["lost","raised","wasted","hid"],"explanation":"raised money 筹到钱。"},{"q":"9","answer":"C","options":["break","lose","make","hide"],"explanation":"make a difference 带来改变。"},{"q":"10","answer":"D","options":["throw","sell","lose","take"],"explanation":"take part 参加。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'A Small Act of Kindness', 'It was a cold winter evening when I saw an old man sitting outside a shop. He looked (1)____ and was holding a small cardboard sign. Most people walked past without even (2)____ at him. At first, I was not sure what to (3)____. Then I remembered the warm soup my mother had packed for me. I walked over and (4)____ it to him with a smile. His tired face suddenly lit up with (5)____. "Thank you, young man," he said softly. That simple moment (6)____ my whole evening. I realised that helping someone does not always (7)____ a lot of money. Sometimes a small, (8)____ act is enough to change someone''s day. Since then, I always try to be (9)____ to people in need. Kindness, I have learned, is a gift that makes both people (10)____.', 137, 2, '[{"q":"1","answer":"A","options":["cold","happy","rich","proud"],"explanation":"looked cold 看起来很冷。"},{"q":"2","answer":"B","options":["eating","looking","sleeping","buying"],"explanation":"without even looking 甚至看都不看。"},{"q":"3","answer":"C","options":["eat","buy","do","sell"],"explanation":"what to do 该做什么。"},{"q":"4","answer":"D","options":["threw","sold","hid","offered"],"explanation":"offered it to him 把它递给他。"},{"q":"5","answer":"A","options":["gratitude","anger","fear","boredom"],"explanation":"lit up with gratitude 满是感激。"},{"q":"6","answer":"B","options":["ruined","brightened","wasted","darkened"],"explanation":"brightened my evening 照亮了我的夜晚。"},{"q":"7","answer":"C","options":["eat","break","need","lose"],"explanation":"does not need a lot of money 不需要很多钱。"},{"q":"8","answer":"D","options":["cruel","lazy","rude","kind"],"explanation":"a small, kind act 小小的善举。"},{"q":"9","answer":"A","options":["helpful","rude","lazy","cruel"],"explanation":"be helpful to people 乐于助人。"},{"q":"10","answer":"B","options":["jealous","happy","bored","angry"],"explanation":"makes both people happy 让双方都快乐。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U3', 'Why Do People Give?', 'Have you ever wondered why people (1)____ money to strangers they will never meet? Scientists say the main (2)____ is empathy. When we can imagine another person''s (3)____, we naturally want to help. Giving also makes the (4)____ feel good, not just the receiver. Studies show that people who help others often feel (5)____ and less stressed. Of course, a sense of (6)____ matters too. Some people give because they believe it is the (7)____ thing to do. Others give simply because they once received help and want to (8)____ it forward. Whatever the reason, every (9)____ act, big or small, makes the world a little kinder. Perhaps that is why the spirit of giving has lasted for thousands of (10)____.', 121, 2, '[{"q":"1","answer":"C","options":["eat","sell","give","throw"],"explanation":"give money 捐钱。"},{"q":"2","answer":"D","options":["price","noise","engine","reason"],"explanation":"the main reason 主要原因。"},{"q":"3","answer":"A","options":["pain","price","noise","colour"],"explanation":"another person''s pain 他人的痛苦。"},{"q":"4","answer":"B","options":["winner","giver","seller","buyer"],"explanation":"makes the giver feel good 让给予者感觉良好。"},{"q":"5","answer":"C","options":["angrier","sadder","happier","poorer"],"explanation":"feel happier 感到更快乐。"},{"q":"6","answer":"D","options":["weather","distance","colour","justice"],"explanation":"a sense of justice 正义感。"},{"q":"7","answer":"A","options":["right","wrong","funny","strange"],"explanation":"the right thing to do 该做的正确之事。"},{"q":"8","answer":"B","options":["throw","pay","break","lose"],"explanation":"pay it forward 把善意传递下去。"},{"q":"9","answer":"C","options":["cruel","lazy","kind","rude"],"explanation":"every kind act 每一个善举。"},{"q":"10","answer":"D","options":["minutes","seconds","metres","years"],"explanation":"thousands of years 数千年。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 Planning a Charity Sale', '上外版选择性必修第二册 U3 · dialogue', 3, 'Lucy: Mr Green asked us to plan a charity event for the school. Any ideas?
