INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·短文 The Ice Bucket Challenge', '上外版选择性必修第二册 U3 · passage', 2, 'A few years ago, a fun activity called the Ice Bucket Challenge spread around the world.
