INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·短文 Pass the Kindness On', '上外版选择性必修第二册 U3 · passage', 2, 'Here is a simple way to make the world a little kinder.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a narrative about helping others(写一篇助人经历的记叙文)', 'A Kind Deed I Will Never Forget', '假设你是李华,学校报社正在征集''帮助他人''的故事。请用英语写一篇约100–120词的记叙文,讲述你做慈善或帮助别人的一次经历。内容包括:① 时间、地点、人物(setting);② 事情经过(开端·发展·高潮·结尾);③ 你的感受或从中得到的启示。注意:动名词作主语/宾语等结构运用得当,行文连贯。', 'Suppose you are Li Hua. Your school Newspaper Club is collecting stories about helping others. Write a narrative of about 100–120 words about a time you did charity work or a kind deed. Include: 1) the setting (time, place, people); 2) what happened (beginning, rising action, climax, end); 3) your feelings or the lesson you learned. Use -ing forms (as subject/object) naturally and keep the story connected.', '["交代背景 setting(时间/地点/人物)","按顺序叙述经过(开端→发展→高潮→结尾)","结尾点出感受或启示(Helping others … / I realised that …)","动名词作主语/宾语等结构运用得当、句句连贯"]'::jsonb, 70, 100, 'Last winter, I saw an old man selling pencils outside our school gate. He looked cold and tired, and few people stopped to buy from him. Remembering the warm gloves in my bag, I walked over and bought several pencils. Then I quietly gave him my gloves and a cup of hot tea. His face lit up with a bright smile, and he thanked me again and again. That moment filled my heart with warmth. As I walked home, I realised that helping others does not need much money or time. A small act of kindness can warm both the giver and the receiver, even on the coldest day.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Remembering the warm gloves in my bag, I walked over and bought several pencils.","His face lit up with a bright smile, and he thanked me again and again.","Helping others does not need much money or time.","A small act of kindness can warm both the giver and the receiver, even on the coldest day."]'::jsonb, '[{"wrong":"I enjoy to help others.","correct":"I enjoy helping others.","note":"enjoy 后只接动名词,不接 to do。"},{"wrong":"Thank you for help me that day.","correct":"Thank you for helping me that day.","note":"介词 for 后接动名词 helping。"},{"wrong":"Helping others are very rewarding.","correct":"Helping others is very rewarding.","note":"动名词作主语视作单数,谓语用 is。"}]'::jsonb, '【助人记叙文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U3', '{"title":"动名词(-ing)作主语 / 宾语速查","intro":"动词加 -ing 变成动名词,具有名词性质,可作主语、动词宾语和介词宾语。判断口诀:句首/介词后 → 用 -ing;特定动词(enjoy/finish/mind 等)后 → 用 -ing。","table":{"headers":["用法","例句 / 说明"],"rows":[["作主语(单数)","Helping others is rewarding.(动名词作主语,谓语用单数 is)"],["作动词宾语","She enjoys volunteering.(enjoy/admit/avoid/finish/mind/suggest/keep/practise 等后接 -ing)"],["作介词宾语","Thank you for helping.(for/at/in/of/by/without/instead of + -ing)"],["固定搭配 to + -ing","look forward to / be used to / be committed to + doing(此处 to 是介词)"]]},"specialRules":[{"rule":"动名词作主语时被看作一个整体,谓语动词用单数","mark":"Giving makes us happy(makes 不用 make)"},{"rule":"这些动词后只接 -ing 不接 to do:enjoy, finish, mind, admit, avoid, consider, suggest, keep, practise, deny, imagine","mark":"finish cleaning √ / finish to clean ×"},{"rule":"介词后只能接 -ing,不能接 to do","mark":"good at singing √ / good at to sing ×"},{"rule":"look forward to / be used to / be devoted to 中的 to 是介词,后接 -ing","mark":"look forward to seeing √ / to see ×"}],"why":["动名词由动词变来,但具有名词性质,所以能像名词一样作主语和宾语;作主语时表示泛指或经常性的行为,被看作单数,谓语用单数。"],"gaokaoPoints":["动名词作主语 vs 不定式作主语:-ing 多表泛指/经常性(Seeing is believing),to do 多表具体一次的行为;作动词/介词宾语时按固定搭配只能用 -ing。","动词后接 -ing 还是 to do:remember/forget/stop/try + doing(已做)与 + to do(将做)含义不同,是高频考点。"],"examVsReal":[{"exam":"Seeing is believing.(谚语/书面)","real":"You have to see it to believe it.","note":"考试爱考动名词作主语;真实口语常换成更口语化的句式"},{"exam":"I look forward to hearing from you.(书面/考试)","real":"Can''t wait to hear from you!","note":"to 后用 -ing 是考点;真实口语常用 can''t wait to do"}]}'::jsonb, 'sufe');
